// Extract message details from Telegram trigger
const msg = $input.first().json.message || $input.first().json;
const chatId = msg.chat?.id || msg.from?.id;
const userId = msg.from?.id;
const username = msg.from?.username || 'unknown';
const firstName = msg.from?.first_name || '';
const lastName = msg.from?.last_name || '';
const text = msg.text || '';
const languageCode = msg.from?.language_code || 'ar';

// Detect language from message content
function detectLanguage(text) {
  const arabicRegex = /[\u0600-\u06FF]/;
  const frenchWords = /\b(bonjour|merci|comment|est-ce|je|tu|nous|vous|les|des|une|pour)\b/i;
  if (arabicRegex.test(text)) return 'arabic';
  if (frenchWords.test(text)) return 'french';
  return 'english';
}

return [{
  json: {
    chatId,
    userId,
    username,
    firstName,
    lastName,
    fullName: `${firstName} ${lastName}`.trim(),
    text,
    detectedLanguage: detectLanguage(text),
    telegramLanguage: languageCode,
    timestamp: new Date().toISOString()
  }
}];

