// Parse AI response and determine routing
const aiResponse = $input.first().json.message?.content || $input.first().json.text;
const messageData = $('Build AI Context').first().json;

let parsed;
try {
  const jsonStr = aiResponse.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  parsed = JSON.parse(jsonStr);
} catch (e) {
  parsed = {
    response: aiResponse,
    confidence: 50,
    category: 'general',
    needs_escalation: true,
    escalation_reason: 'Failed to parse AI structured response',
    suggested_actions: []
  };
}

return [{
  json: {
    chatId: messageData.chatId,
    userId: messageData.userId,
    username: messageData.username,
    fullName: messageData.fullName,
    originalMessage: messageData.text,
    detectedLanguage: messageData.detectedLanguage,
    isKnownUser: messageData.isKnownUser,
    userProfile: messageData.userProfile,
    aiResponse: parsed.response,
    confidence: parsed.confidence || 50,
    category: parsed.category || 'general',
    needsEscalation: parsed.needs_escalation || parsed.confidence < 70,
    escalationReason: parsed.escalation_reason || '',
    suggestedActions: parsed.suggested_actions || [],
    timestamp: new Date().toISOString()
  }
}];

